money=lambda x: ('('+f'${abs(x):,.0f}'+')') if x<0 else f'${x:,.0f}'
num=lambda x:f'{x:,.0f}'
pct=lambda x:f'{x*100:.1f}%'
def table(headers,rows,cls=''):
    return '<table class="'+cls+'"><thead><tr>'+''.join('<th>'+str(v)+'</th>' for v in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'
def note(text):return '<aside>'+text+'</aside>'
def cite(*ids):return '<span class="cite">'+', '.join('<a href="#source-'+i+'">['+i+']</a>' for i in ids)+'</span>'
def lead(text):return '<p class="lead">'+text+'</p>'
def cols(a,b):return '<div class="cols"><div>'+a+'</div><div>'+b+'</div></div>'
def cards(items):return '<div class="cards">'+''.join('<div><span>'+a+'</span><strong>'+b+'</strong><p>'+c+'</p></div>' for a,b,c in items)+'</div>'
pages=[]
def page(kicker,title,body,cls=''):
    pages.append(dict(kicker=kicker,title=title,body=body,cls=cls))

